    /// <summary>
    /// Customer Tobacco validations while creating Sales order
    /// </summary>
    /// <param name="sender">Get Table buffer</param>
    /// <param name="e"> Get Sales Table args</param>
    [
        DataEventHandler(tableStr(SalesTable), DataEventType::Inserting),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")        
    ]
    public static void SalesTable_onInserting(Common sender, DataEventArgs e)
    {
        SalesTable salesTable = sender as SalesTable;
        CustTable   custTable;
        custTable = custTable::find(salesTable.CustAccount, false);
        if(METCustParameters::Find().ValidateTobaccoLicence
            && LogisticsAddressState::find(custTable.PartyCountry, custTable.PartyState).METValidateTobaccoLicence)
        {
            salesTable.METTobaccoLicenceValidationRequired = NoYes::Yes;
            salesTable.METValidTobaccoLicence = NoYes::Yes;
            if(METCustTobaccoLicenseTable::find(custTable.AccountNum).TobaccoLicenceExpiry < salesTable.ShippingDateRequested)
            {
                salesTable.METCustTobaccoReasonCode = LogisticsAddressState::find(custTable.PartyCountry, custTable.PartyState).METTobaccoReasonCode;
            }
        }
        else
        {
            salesTable.METTobaccoLicenceValidationRequired = NoYes::No;
            salesTable.METValidTobaccoLicence = NoYes::No;            
        }

    }
